// This file is generated by AI.

// 引擎条目与"项目用哪个引擎"的断言。

import { describe, expect, it } from 'vitest';

import { engineLabel, findEngine, makeEngineEntry, parseEngineManifest, resolveProjectEngine } from '../src/lib/engine';
import { bindingKey, findBinding, withBinding } from '../src/lib/bindings';
import type { EngineEntry } from '../src/lib/settings';

const engines: EngineEntry[] = [
  { id: 'eng-1', name: 'WebGAL', version: '4.6.4', path: 'C:\\engine\\4.6.4' },
  { id: 'eng-2', name: 'WebGAL', version: '4.5.0', path: 'C:\\engine\\4.5.0' },
];

describe('parseEngineManifest', () => {
  it('读取 webgal-engine.json 的名称与运行时版本', () => {
    expect(
      parseEngineManifest({ id: 'open-webgal.webgal', name: 'WebGAL', version: '4.6.4', webgalVersion: '4.6.4' })
    ).toEqual({
      name: 'WebGAL',
      version: '4.6.4',
      manifestId: 'open-webgal.webgal',
      icon: undefined,
    });
  });

  it('优先使用 webgalVersion, 没有时退回 version (package.json)', () => {
    expect(parseEngineManifest({ name: 'webgal-engine', version: '4.5.0' }).version).toBe('4.5.0');
    expect(parseEngineManifest({ version: '1.0.0', webgalVersion: '4.6.0' }).version).toBe('4.6.0');
  });

  it('不是对象或字段为空时给出空信息', () => {
    expect(parseEngineManifest(null)).toEqual({});
    expect(parseEngineManifest({ name: '   ' })).toEqual({
      name: undefined,
      version: undefined,
      manifestId: undefined,
      icon: undefined,
    });
  });
});

describe('makeEngineEntry / engineLabel / findEngine', () => {
  it('有自述文件时用它的名称, 否则用目录名', () => {
    expect(makeEngineEntry('C:\\e\\WebGAL 4.6.4', { name: 'WebGAL', version: '4.6.4' }, 'eng-x').name).toBe('WebGAL');
    const fallback = makeEngineEntry('C:\\e\\WebGAL 4.6.4', undefined, 'eng-y');
    expect(fallback.name).toBe('WebGAL 4.6.4');
    expect(fallback.version).toBeUndefined();
  });

  it('显示名带上版本', () => {
    expect(engineLabel(engines[0])).toBe('WebGAL 4.6.4');
    expect(engineLabel({ id: 'eng-3', name: '自建引擎', path: 'C:\\e' })).toBe('自建引擎');
  });

  it('按 id 查找', () => {
    expect(findEngine(engines, 'eng-2')?.path).toBe('C:\\engine\\4.5.0');
    expect(findEngine(engines, undefined)).toBeNull();
    expect(findEngine(engines, '不存在')).toBeNull();
  });
});

describe('resolveProjectEngine', () => {
  it('项目绑定优先', () => {
    const bindings = { [bindingKey('C:\\proj\\game')]: { engineId: 'eng-2' } };
    expect(resolveProjectEngine({ engines }, bindings, 'C:\\proj\\game')?.id).toBe('eng-2');
  });

  it('绑定路径大小写不同也能命中', () => {
    const bindings = { [bindingKey('C:\\Proj\\Game')]: { engineId: 'eng-2' } };
    expect(resolveProjectEngine({ engines }, bindings, 'c:\\proj\\game')?.id).toBe('eng-2');
  });

  it('没有绑定时返回 null (不存在"默认引擎")', () => {
    expect(resolveProjectEngine({ engines }, {}, 'C:\\proj')).toBeNull();
  });

  it('绑定指向已移除的引擎时也返回 null, 不悄悄回落到别的引擎', () => {
    const bindings = { [bindingKey('C:\\proj')]: { engineId: 'eng-已删除' } };
    expect(resolveProjectEngine({ engines }, bindings, 'C:\\proj')).toBeNull();
  });

  it('没有引擎或没有项目时返回 null', () => {
    expect(resolveProjectEngine({ engines: [] }, {}, 'C:\\proj')).toBeNull();
    expect(resolveProjectEngine({ engines }, {}, null)).toBeNull();
  });
});

describe('项目绑定查找/写入', () => {
  it('大小写不同的历史键也能查到', () => {
    const bindings = { [bindingKey('C:\\Proj\\Game')]: { templateId: 'tpl-1' } };
    expect(findBinding(bindings, 'c:\\proj\\game')?.templateId).toBe('tpl-1');
    expect(findBinding(bindings, 'C:\\Proj\\Game')?.templateId).toBe('tpl-1');
  });

  it('没有该项目的绑定时返回 undefined', () => {
    expect(findBinding({}, 'C:\\proj')).toBeUndefined();
    expect(findBinding({ [bindingKey('C:\\other')]: {} }, 'C:\\proj')).toBeUndefined();
  });

  it('写入时清掉同一项目的大小写变体', () => {
    const bindings = { [bindingKey('c:\\proj')]: { templateId: 'tpl-old' } };
    const next = withBinding(bindings, 'C:\\Proj', { engineId: 'eng-1' });
    expect(Object.keys(next)).toEqual([bindingKey('C:\\Proj')]);
    expect(next[bindingKey('C:\\Proj')]).toEqual({ engineId: 'eng-1' });
  });

  it('写入不相关的项目时保留其它绑定', () => {
    const bindings = { [bindingKey('C:\\a')]: { engineId: 'eng-1' } };
    const next = withBinding(bindings, 'C:\\b', { engineId: 'eng-2' });
    expect(Object.keys(next)).toHaveLength(2);
  });
});
